    def __init__(self):
        self.dd = {}
        self.tot = 0

    def insert(self, val):
        if val not in self.dd:
            self.dd[val] = [0, None, None]
            self.tot += 1
        self.dd[val][0] += 1

    def erase(self, val):
        if val in self.dd:
            self.dd[val][0] -= 1
            if self.dd[val][0] == 0:
                self.delete(val)

    def query(self, val):
        if val in self.dd:
            return self.dd[val][0]
        return 0

    def delete(self, val):
        self.tot -= 1
        lst = self.dd[val]
        if lst[1] and lst[2]:
            c = self.steal(lst[1], lst[2])
            self.dd[val] = c
        elif lst[1]:
            self.dd[val] = self.dd[lst[1]]
            self.dd.pop(lst[1], None)
        else:
            self.dd[val] = self.dd[lst[2]]
            self.dd.pop(lst[2], None)
        self.rebalance(val)

    def steal(self, lef, righ):
        if self.dd[lef][2]:
            c = self.steal(lef, self.dd[lef][2])
            self.dd[lef][2] = c
            return self.dd[lef]
        else:
            yz = self.dd[lef]
            self.dd.pop(lef, None)
            return yz

    def getHeight(self, val):
        if val not in self.dd:
            return 0
        return max(self.dd[val][1], self.dd[val][2]) + 1

    def rebalance(self, val):
        h = self.getHeight(val)
        if h == 0:
            self.dd.pop(val, None)
            return
        elif h == 1:
            self.dd[val][1] = self.dd[val][2] = 0
