            self.dd[val][1] = self.getHeight(self.dd[val][1])
            self.dd[val][2] = self.getHeight(self.dd[val][2])

    def rotateLeft(self, val):
        yz = self.dd[val][2]
        self.dd[val][2] = self.dd[yz][1]
        self.dd[yz][1] = val
        self.dd[ val ][1] = max(self.dd[val][1], self.dd[val][2]) + 1
